  "anomalies": [
    {
      "category": "other",
      "components": ["U2", "U3"],
      "pins": ["U2.2", "U2.3", "U3.7", "U3.2", "U3.3"],
      "nets": ["SCK", "POT", "TACH"],
      "observed": "U2 (ATtiny45-20P) connects SCK to PB3 (pin 2) and POT to PB4 (pin 3) and has no TACH connection, while U3 (ATtiny13V-10S) connects SCK to PB2 (pin 7), POT to PB3 (pin 2) and TACH to PB4 (pin 3).",
      "expected": "The two alternative ATtiny footprints should have identical pin assignments (SCK=PB2, POT=PB3, TACH=PB4) so the same firmware works with either build.",
      "evidence": [
        {"source": "schematic", "quote": "U2 ATtiny45-20P: XTAL1/PB3 (pin 2) -> SCK, XTAL2/PB4 (pin 3) -> POT"},
        {"source": "schematic", "quote": "U3 ATtiny13V-10S: PB2 (pin 7) -> SCK, PB3 (pin 2) -> POT, PB4 (pin 3) -> TACH"}
      ],
      "impact": "A board built with U2 cannot read the fan tachometer and uses different SCK/POT pins than a U3 build, so one firmware image cannot serve both options.",
      "confidence": 0.6
    },
    {
      "category": "other",
      "components": ["R3", "R6"],
      "pins": ["R3.1", "R6.1"],
      "nets": ["VCC", "RST", "TACH"],
      "observed": "R3 pulls the RST net up to VCC and R6 pulls the TACH net up to VCC.",
      "expected": "RST and TACH are 5V logic signals (the ATtiny runs from +5V), so their pull-ups should return to +5V, not to VCC, which is the input of the LM1117-5.0 and therefore higher than 5V.",
      "evidence": [
        {"source": "schematic", "quote": "R3 10K: top -> VCC, bottom -> RST; R6 10K: top -> VCC, bottom -> TACH"},
        {"source": "schematic", "quote": "U1 LM1117-5.0: VIN <- VCC, VO -> +5V"}
      ],
      "impact": "RST and TACH would be pulled to the higher VCC rail, exceeding the ATtiny's absolute maximum ratings and potentially damaging the MCU or the fan tach input.",
      "confidence": 0.5
    }
  ],
  "summary": "The schematic contains two deviations: the two alternative ATtiny footprints (U2/U3) have inconsistent pin assignments, and the RST/TACH pull-ups (R3/R6) return to the unregulated VCC rail instead of the +5V logic rail."
}

